#!/usr/bin/env python3
"""
创建完整的拼音数据库
包含所有常用汉字和词语
生成4列格式：词语\t拼音\t快捷码\thash值
"""

import subprocess
import sys

# 尝试安装依赖
try:
    from xpinyin import Pinyin
except ImportError:
    print("正在安装依赖包...")
    subprocess.check_call([sys.executable, "-m", "pip", "install", "xpinyin"])
    from xpinyin import Pinyin

def calculate_shortcut(text):
    """计算快捷码 - 每个拼音的首字母
    使用与Swift相同的算法：a=20, b=21, ..., z=45
    组合方式：reduce(0, { $0 * 100 + $1 })
    """
    pinyin_converter = Pinyin()
    letters = []
    for char in text:
        if '\u4e00' <= char <= '\u9fff':  # 中文字符
            py = pinyin_converter.get_pinyin(char, '')
            if py:
                letters.append(py[0])
        else:
            # 对于非中文字符，直接使用（但只取字母）
            if char.isalpha():
                letters.append(char.lower())

    # 将字母转换为数字代码（与Swift的intercode相同）
    letter_to_code = {
        'a': 20, 'b': 21, 'c': 22, 'd': 23, 'e': 24, 'f': 25, 'g': 26, 'h': 27, 'i': 28,
        'j': 29, 'k': 30, 'l': 31, 'm': 32, 'n': 33, 'o': 34, 'p': 35, 'q': 36, 'r': 37,
        's': 38, 't': 39, 'u': 40, 'v': 41, 'w': 42, 'x': 43, 'y': 44, 'z': 45
    }

    codes = []
    for letter in letters:
        if letter in letter_to_code:
            codes.append(letter_to_code[letter])

    # 限制最多9个字母
    if len(codes) > 9:
        codes = codes[:9]

    # 组合代码（与Swift的combined()相同）
    result = 0
    for code in codes:
        result = result * 100 + code

    return result

def calculate_ping(text):
    """计算hash值，与Swift String.hash兼容"""
    hash_val = 0
    for char in text:
        hash_val = (hash_val * 31 + ord(char)) & 0xFFFFFFFF
    return hash_val if hash_val > 0 else 1

