def generate_pinyin_lexicon():
    """生成完整的拼音词库"""
    pinyin_converter = Pinyin()

    # 获取所有字符和词语
    chars = get_all_common_characters()
    words = get_all_common_words()

    all_entries = []
    seen = set()

    print(f"开始生成拼音词库...")
    print(f"汉字数量: {len(chars)}")
    print(f"词语数量: {len(words)}")

    # 处理单字
    for char in chars:
        if char in seen:
            continue
        pinyin = pinyin_converter.get_pinyin(char, splitter='\'')
        if pinyin:
            shortcut = calculate_shortcut(char)
            ping = calculate_ping(pinyin)
            all_entries.append((char, pinyin, shortcut, ping))
            seen.add(char)

    # 处理词语
    for word in words:
        if word in seen:
            continue
        pinyin = pinyin_converter.get_pinyin(word, splitter='\'')
        if pinyin:
            shortcut = calculate_shortcut(word)
            ping = calculate_ping(pinyin)
            all_entries.append((word, pinyin, shortcut, ping))
            seen.add(word)

    print(f"总共生成: {len(all_entries)} 条词条")
    return all_entries

def main():
    print("正在创建完整的拼音数据库...")
    entries = generate_pinyin_lexicon()

    # 写入文件
    output_path = "/Users/colin/develop/TypeDuck-Mac/Preparing/Sources/Preparing/Resources/pinyin.txt"

    with open(output_path, 'w', encoding='utf-8') as f:
        for word, pinyin, shortcut, ping in entries:
            f.write(f"{word}\t{pinyin}\t{shortcut}\t{ping}\n")

    print(f"\n已写入 {len(entries)} 条词条到 {output_path}")
    print("\n示例词条（单字）:")
    for entry in entries[100:120]:
        print(f"  {entry[0]}\t{entry[1]}\t{entry[2]}\t{entry[3]}")

    print("\n示例词条（词语）:")
    word_entries = [e for e in entries if len(e[0]) >= 2]
    for entry in word_entries[50:70]:
        print(f"  {entry[0]}\t{entry[1]}\t{entry[2]}\t{entry[3]}")

if __name__ == "__main__":
    main()
